import hashlib
import hmac
import os
import time
import struct
from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import urllib.parse
import secrets

SECRET_KEY = os.environ.get('SECRET_KEY', secrets.token_hex(32))
SESSION_DURATION = int(os.environ.get('SESSION_DURATION', '3600'))
BIND_HOST = os.environ.get('BIND_HOST', '127.0.0.1')
BIND_PORT = int(os.environ.get('BIND_PORT', '8080'))

# In-memory user store (would be database in production)
USERS = {}
ACTIVE_SESSIONS = {}

def constant_time_compare(a: bytes, b: bytes) -> bool:
    """Compare two byte strings in constant time."""
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= x ^ y
    return result == 0

def create_token(user_id: str, issued_at: int) -> str:
    """Create an authenticated session token.
    Format: user_id.issued_at.signature
    Signature is HMAC-SHA256, truncated to 16 bytes for compact tokens.
    """
    payload = f"{user_id}.{issued_at}"
    mac = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).digest()
    # Truncate to 16 bytes for compact token representation
    sig_bytes = mac[:16]
    sig_hex = sig_bytes.hex()
    return f"{payload}.{sig_hex}"

def verify_token(token: str) -> dict:
    """Verify a session token and return claims if valid.
    Returns dict with 'valid', 'user_id', 'issued_at' keys.
    """
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return {'valid': False, 'error': 'malformed token'}

        user_id, issued_at_str, provided_sig = parts
        issued_at = int(issued_at_str)

        # Check token expiration
        current_time = int(time.time())
        if current_time - issued_at > SESSION_DURATION:
            return {'valid': False, 'error': 'token expired'}

        if issued_at > current_time + 60:  # Allow 60s clock skew
            return {'valid': False, 'error': 'token from future'}

        # Recompute expected signature
        payload = f"{user_id}.{issued_at_str}"
        expected_mac = hmac.new(
            SECRET_KEY.encode(), payload.encode(), hashlib.sha256
        ).digest()
        expected_sig = expected_mac[:16].hex()

        # Verify signature - must be exact length match
        provided_bytes = bytes.fromhex(provided_sig)
        expected_bytes = bytes.fromhex(expected_sig)

        # Require exact 16-byte signature length
        if len(provided_bytes) != 16:
            return {'valid': False, 'error': 'invalid signature length'}

        if constant_time_compare(provided_bytes, expected_bytes):
            return {'valid': True, 'user_id': user_id, 'issued_at': issued_at}
        else:
            return {'valid': False, 'error': 'invalid signature'}
    except (ValueError, IndexError, struct.error) as e:
        return {'valid': False, 'error': f'token parse error'}

def hash_password(password: str, salt: bytes = None) -> tuple:
    """Hash password with PBKDF2-HMAC-SHA256."""
    if salt is None:
        salt = os.urandom(32)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return dk, salt

def verify_password(password: str, stored_hash: bytes, salt: bytes) -> bool:
    """Verify password against stored hash."""
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return constant_time_compare(dk, stored_hash)

class AuthHandler(BaseHTTPRequestHandler):
    def send_json(self, status: int, data: dict):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def get_request_body(self) -> dict:
        try:
            content_length = int(self.headers.get('Content-Length', 0))
        except (TypeError, ValueError):
            return None
        if content_length < 0 or content_length > 4096:  # Limit body size
            return None
        if content_length == 0:
            return {}
        body = self.rfile.read(content_length)
        # Gracefully handle malformed JSON instead of raising an
        # unhandled exception (avoids stack-trace disclosure / crash).
        try:
            return json.loads(body)
        except (json.JSONDecodeError, ValueError):
            return None

    def authenticate_request(self) -> dict:
        """Extract and verify token from Authorization header."""
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return {'valid': False, 'error': 'missing auth'}
        token = auth_header[7:]
        return verify_token(token)

    def do_POST(self):
        parsed = urllib.parse.urlparse(self.path)

        if parsed.path == '/api/register':
            self.handle_register()
        elif parsed.path == '/api/login':
            self.handle_login()
        elif parsed.path == '/api/refresh':
            self.handle_refresh()
        else:
            self.send_json(404, {'error': 'not found'})

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)

        if parsed.path == '/api/profile':
            self.handle_profile()
        elif parsed.path == '/api/health':
            self.send_json(200, {'status': 'ok'})
        else:
            self.send_json(404, {'error': 'not found'})

    def handle_register(self):
        body = self.get_request_body()
        if not body:
            self.send_json(400, {'error': 'invalid body'})
            return

        username = body.get('username', '').strip()
        password = body.get('password', '')

        if not username or len(username) < 3 or len(username) > 64:
            self.send_json(400, {'error': 'invalid username'})
            return

        if not password or len(password) < 8:
            self.send_json(400, {'error': 'password too short'})
            return

        # Only allow alphanumeric usernames
        if not username.isalnum():
            self.send_json(400, {'error': 'username must be alphanumeric'})
            return

        if username in USERS:
            self.send_json(409, {'error': 'user exists'})
            return

        pw_hash, salt = hash_password(password)
        USERS[username] = {'hash': pw_hash, 'salt': salt}
        self.send_json(201, {'message': 'registered', 'user': username})

    def handle_login(self):
        body = self.get_request_body()
        if not body:
            self.send_json(400, {'error': 'invalid body'})
            return

        username = body.get('username', '').strip()
        password = body.get('password', '')

        if username not in USERS:
            # Perform dummy hash to prevent timing oracle
            hash_password('dummy_password')
            self.send_json(401, {'error': 'invalid credentials'})
            return

        user = USERS[username]
        if not verify_password(password, user['hash'], user['salt']):
            self.send_json(401, {'error': 'invalid credentials'})
            return

        issued_at = int(time.time())
        token = create_token(username, issued_at)
        session_id = secrets.token_hex(16)
        ACTIVE_SESSIONS[session_id] = {
            'user_id': username,
            'issued_at': issued_at
        }

        self.send_json(200, {
            'token': token,
            'expires_in': SESSION_DURATION,
            'session_id': session_id
        })

    def handle_refresh(self):
        auth = self.authenticate_request()
        if not auth['valid']:
            self.send_json(401, {'error': auth.get('error', 'unauthorized')})
            return

        issued_at = int(time.time())
        token = create_token(auth['user_id'], issued_at)
        self.send_json(200, {'token': token, 'expires_in': SESSION_DURATION})

    def handle_profile(self):
        auth = self.authenticate_request()
        if not auth['valid']:
            self.send_json(401, {'error': auth.get('error', 'unauthorized')})
            return

        user_id = auth['user_id']
        self.send_json(200, {
            'user_id': user_id,
            'session_issued': auth['issued_at'],
            'message': f'Hello, {user_id}!'
        })

    def log_message(self, format, *args):
        # Suppress default logging to avoid info disclosure
        pass

if __name__ == '__main__':
    server = HTTPServer((BIND_HOST, BIND_PORT), AuthHandler)
    print(f"Auth server running on {BIND_HOST}:{BIND_PORT}")
    server.serve_forever()
